import "slices"

func GroupBySeq[T any, K comparable](seq iter.Seq[T], keyFn func(T) K) map[K][]T {
    out := make(map[K][]T)
    for v := range seq {
        k := keyFn(v) // 只算一次 key，别在 append 里重复调
        out[k] = append(out[k], v)
    }
    return out
}

groups := GroupBySeq(slices.Values(orders), func(o Order) string { return o.Status }) 1.27 泛型方法时代 1.27 放开泛型方法，分组逻辑能直接长在具体类型上： type Items[T any] []T

func (s Items[T]) GroupBy[K comparable](keyFn func(T) K) map[K][]T {
    out := make(map[K][]T)
    for _, v := range s {
        out[keyFn(v)] = append(out[keyFn(v)], v)
    }
    return out
