    Read(p []byte) (n int, err error)
}
type Writer interface {
    Write(p []byte) (n int, err error)
}
type Closer interface {
    Close() error
}

type ReadCloser interface {
    Reader
    Closer
}
type ReadWriteCloser interface {
    Reader
    Writer
    Closer
} 接口从单接口组合成双接口、三接口： 接口 方法数 组合 典型用途 Reader 1 — 一切可读数据源 Writer 1 — 一切可写目标 ReadCloser 2 Reader + Closer HTTP Body，读完即关 ReadWriter 2 Reader + Writer net.Conn 双向流 ReadWriteCloser 3 Reader + Writer + Closer 完整可读写流 Read 契约与正确读法 Read 的契约是"能读多少算多少"：返回 n < len(p) 且 err == nil 完全合法。调用方必须循环读，不能假设一次填满缓冲： func readAll(r io.Reader) ([]byte, error) {
    buf := make([]byte, 0, 1024)
    tmp := make([]byte, 1024)
    for {
        n, err := r.Read(tmp)
        if n > 0 {
            buf = append(buf, tmp[:n]...) // 先处理数据
        }
        if err != nil {
            if err == io.EOF {
                return buf, nil // EOF 是正常结束
            }
            return buf, err
        }
    }
} 想确保读满指定字节数，直接用 io.ReadFull ；搬粗活用 io.Copy ，它自带 32KB 缓冲，还会探测 ReaderFrom / WriterTo 走零拷贝路径。 装饰器模式 io 包用装饰器层层包裹 Reader，每一层都是新的 io.Reader，可继续装饰。看一个三层嵌套怎么从原文件走到最终 Reader： // 从 gzip 压缩的文件中最多读 1024 字节
