defer f.Close()

r := io.LimitReader(
    gzip.NewReader(f),
    1024,
)
// r 仍是 io.Reader，可传给任何接受 Reader 的函数 装饰器 作用 io.TeeReader(r, w) 读 r 时镜像写一份到 w io.MultiReader(r1, r2...) 串联多个 Reader 依次读完 io.MultiWriter(w1, w2...) 写入广播给所有 writer io.SectionReader 只读指定区间 io.NopCloser(r) 给 Reader 套一个空 Close 缓冲 vs 非缓冲 维度 非缓冲（直接 Read/Write） 缓冲（bufio） 系统调用 每次 Read 一次 syscall 填满缓冲才 syscall 适合场景 大块一次性传输 小块频繁读写 1000 次 1 字节

