  schema/
    user.ts        # User type + resolver
    post.ts        # Post type + resolver
    index.ts       # 合并 typeDefs/resolvers
  context.ts       # 每个请求的 context
  datasource.ts    # 数据访问层
  server.ts        # 启动入口
  plugins.ts       # 插件（日志/埋点） 入口长这样，重点是 context 工厂和 plugins ： // server.ts
import { ApolloServer } from '@apollo/server';
import { expressMiddleware } from '@apollo/server/express4';
import express from 'express';
import { typeDefs, resolvers } from './schema';

const app = express();
const server = new ApolloServer({
  typeDefs,
  resolvers,
  formatError: (err) => {
    // 线上别把 stack 泄露给前端
    if (err.extensions?.code === 'INTERNAL_SERVER_ERROR') {
      return new Error('Internal server error');
    }
    return err;
  },
});
await server.start();

app.use('/graphql', express.json(), expressMiddleware(server, {
  context: async ({ req }) => ({
    user: authenticate(req.headers.authorization),
    loaders: createLoaders(), // 每请求新建，关键！
  }),
}));
app.listen(4000, () => console.log('🚀 on :4000')); Apollo Server 3 → 4 的迁移大坑 很多老教程还在用 new ApolloServer({ typeDefs, resolvers }); server.applyMiddleware() 。4.x 必须先 await server.start() 再挂中间件，而且 standalone 和 express 分了两个包。跟着老文档抄会直接报 You need to call the .start() method ，别怀疑人生。 DataLoader：批量+缓存，GraphQL 的救星 刚学 GraphQL 时写 resolver 很容易这样： // 反面教材：N+1
