type User @key(fields: "id") {
  id: ID!
  name: String!
  email: String!
} 订单服务想给 User 加订单列表，不用改用户服务，自己在子图里扩展： # orders 子图
extend type User @key(fields: "id") {
  id: ID! @external
  orders: [Order!]!
