import { Module } from '@nestjs/common'
import { UsersService } from './users.service'
import { UsersController } from './users.controller'

@Module({
  controllers: [UsersController],
  providers: [UsersService],
  exports: [UsersService], // 别的模块要用 UsersService 就 import 这个模块
})
export class UsersModule {} // users/users.service.ts
import { Injectable } from '@nestjs/common'

@Injectable() // 标记这是个可注入的 Provider
export class UsersService {
  private users = new Map<number, { id: number; name: string }>()

  findById(id: number) {
    return this.users.get(id)
  }

  create(id: number, name: string) {
    this.users.set(id, { id, name })
    return this.users.get(id)
  }
} // users/users.controller.ts
import { Controller, Get, Param, Post, Body } from '@nestjs/common'
import { UsersService } from './users.service'

@Controller('users')
export class UsersController {
  constructor(private readonly users: UsersService) {}

  @Get(':id')
  findOne(@Param('id') id: string) {
    return this.users.findById(Number(id))
  }

  @Post()
  create(@Body() body: { id: number; name: string }) {
    return this.users.create(body.id, body.name)
  }
} 依赖注入：DI 容器在背后干什么 很多人第一次看 NestJS 代码，最懵的就是构造函数里突然多了个 private readonly users: UsersService ，然后就能

Protocol Buffers 2026 - 资深码农 ~$ 资深码农 后端 数据库 AI 运维 前端 工具 游戏 系统 更多 首页 / 后端与编程语言 / Protocol Buffers Protocol Buffers 2026 2026-09-17 后端 / 序列化 约 18 分钟 本文要点： Protocol Buffers（Protobuf）是 Google 开源的语言中立、平台中立的结构化数据序列化框架，广泛用于微服务间通信（gRPC）、数据存储和配置管理。2024 年起 Protobuf 从 proto2/proto3 双轨制转向 Editions 年度发布模型， Edition 2026 已于 2026 年 8 月 20 日随 protoc v36.0 正式发布，带来 STRICT 符号可见性、STYLE2026 命名规范、PROTO_LIMITS2026 结构限制三大默认行为变更。 我在生产上跟着 Editions 从 2023 升到 2026，最大的体会是：wire format 没变，老服务不用一次性动，按模块灰度迁就行。这篇把版本演进、特性层级和迁移坑一次讲透。 一、什么是 Protocol Buffers Protocol Buffers 是一种 语言中立、平台中立、可扩展的结构化数据序列化机制 。你通过 .proto 文件定义数据结构（IDL），然后用 protoc 编译器生成各种语言的代码，用于序列化和反序列化数据。 1.1 核心优势 特性 Protobuf JSON XML 序列化后体积 极小（二进制） 中等（文本） 大（文本+标签） 序列化速度 极快 中等 慢 Schema 校验 编译时强类型 运行时/可选 DTD/XSD 向前/向后兼容 原生支持（字段编号） 需手动处理 需手动处理 可读性 不可读（需反序列化） 可读 可读 适用场景 微服务 RPC、存储 API、配置 文档、配置 1.2 一个最简单的例子 // user.proto
edition = "2026";

package example.v1;

message User {
  string id = 1;
  string name = 2;
  string email = 3;
  int32 age = 4;
  repeated string tags = 5;
} // Go 使用示例
package main

import (
    "fmt"
    "google.golang.org/protobuf/proto"
    pb "example.com/gen/example/v1"
)

func main() {
    user := &pb.User{
        Id:    "u_001",
        Name:  "张三",
        Email: "zhangsan@example.com",
        Age:   28,
        Tags:  []string{"admin", "vip"},
    }

    // 序列化
    data, _ := proto.Marshal(user)
    fmt.Printf("序列化后 %d 字节\n", len(data))

    // 反序列化
    var decoded pb.User
    proto.Unmarshal(data, &decoded)
    fmt.Printf("姓名: %s\n", decoded.Name)
} 二、从 proto2/proto3 到 Editions 的演进 Protobuf 的语言版本经历了三个阶段： proto2 （2008）、 proto3 （2016）、 Editions （2024 起）。Editions 的核心思想是 将 proto2 和 proto3 的行为差异拆解为可独立切换的"特性"（features） ，不再通过大版本号一刀切。 2.1 Editions 版本与 protoc 对应关系 Edition 最低 protoc 版本 发布日期 核心变更 proto2 2.0 2008 初始版本 proto3 3.0 2016 简化语义、开放 enum Edition 2023 v27.0 2024-08-13 Editions 首次发布 Edition 2024 v32.0 2025-05-23 符号可见性、命名规范 Edition 2026 v36.0 2026-08-20 STRICT、STYLE2026、结构限制 2.2 Editions 特性层级机制 Editions 的特性可以在 四个层级 上设置，内层覆盖外

