let fetcher = async || {
    let data = fetch_data().await;
    process(data).await
};
let result = fetcher().await; gen 块 ：生成器块，简化迭代器编写： // Rust 2024: gen 块
fn fibonacci() -> impl Iterator<Item = u64> {
    gen {
        let mut a = 0;
        let mut b = 1;
        loop {
            yield a;
            let next = a + b;
            a = b;
            b = next;
        }
    }
} 生命周期捕获规则变更 ： impl Trait 返回类型默认捕获所有生命周期。 unsafe_op_in_unsafe_fn 默认启用 ：unsafe 函数内的 unsafe 操作需显式标注。 cfg_select! ：编译时条件选择宏（1.95.0 正式稳定）。 2026 版本线：1.94 → 1.98 版本 发布时间 关键变化 1.94.0 2026-03-06 RISC-V 稳定 29 项 target feature、Unicode 17、Cargo config include、TOML v1.1 1.95.0 2026-04-16 cfg_select! 稳定、闭包捕获更精确、Supertrait Upcasting 1.97.0 2026-07-09 默认 v0 符号改编、整数位操作 API 稳定、Cargo build.warnings 1.98.0 2026-08-20 代数浮点运算方法、 format_into + NumBuffer 稳定（当前最新） 升级建议： rustup update stable 跟随最新线即可；1.95+ 的 lint 与兼容性说明较多，工程升级前过一遍 release notes。 1.98.0：代数浮点与 format_into 代数浮点运算方法 ：在特定代码块中，开发者可告知编译器"这段代码可遵循实数代数性质进行激进重排与并行化"，大幅增强循环向量化（SIMD），成倍提升数值计算效率且不引入未定义行为——对 HPC 与科学计算是重要突破。 format_into ：所有原生整数类型新增该方法，直接把整数格式化写入预分配缓冲区，绕过动态分发，效率与知名 itoa 库相当： // Rust 1.98: 零分配整数格式化
let mut buf = NumBuffer::new();
let n = 12345u64;
