    server 10.0.0.1:8080 weight=3;
    server 10.0.0.2:8080 weight=2;
    keepalive 32;  # 复用后端连接
}

server {
    listen 443 ssl http2;
    server_name example.com;

    location / {
        proxy_pass http://backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_http_version 1.1;
        proxy_set_header Connection "";  # 必须，否则 keepalive 不生效
    }
} 正向代理 vs 反向代理 正向代理 反向代理 代理谁 代理客户端 代理服务端 客户端知道吗 知道（手动配代理） 不知道（以为 Nginx 就是服务器） 典型用途 翻墙、访问控制 负载均衡、SSL 终止 Nginx 支持 1.31.0+ 内置 原生支持 HTTP 跳转 HTTPS server {
    listen 80;
    server_name example.com;
    return 301 https://$host$request_uri;
} 用 $host 而不是 $server_name ，因为 $host 是客户端请求的原始域名，泛域名场景不会出问题。 gzip 压缩 gzip on;
gzip_vary on;
gzip_comp_level 6;  # 默认就是6，性价比最高
gzip_min_length 1024;  # 小于1KB不压
gzip_types text/plain text/css application/json
           application/javascript text/xml image/svg+xml; gzip_comp_level 的坑 level 1 到 9，level 6 是性价比拐点。从 6 到 9，压缩率只多 2%，但 CPU 翻三倍。别图省带宽把 CPU 吃满。图片视频已经是压缩格式了，不要再 gzip。 location 匹配：最容易搞混的部分 优先级： = （精确）> ^~ （前缀优先）> ~ / ~* （正则，按顺序）> 无前缀（最长匹配）。 # 这些写法的区别
