{
    [SerializeField] private float speed = 5f;
    private Rigidbody rb;

    void Awake() { rb = GetComponent<Rigidbody>(); }

    void Update()
    {
        float h = Input.GetAxis("Horizontal");
        float v = Input.GetAxis("Vertical");
        transform.Translate(new Vector3(h, 0, v) * speed * Time.deltaTime);
    }

    void FixedUpdate() { rb.AddForce(Vector3.up * 9.8f); }
} Awake 和 Start 的区别 Awake 实例化就调，哪怕脚本是 disabled 的。Start 要等到脚本启用且第一帧前才调。初始化自己用 Awake，依赖其他 GameObject 的用 Start。我见过太多人把 GetComponent 写在 Start 里，结果 Awake 阶段就被别的脚本访问，拿到 null。 物理系统：别在 Update 里做物理 这是新手最容易犯的错。物理操作必须放在 FixedUpdate 里——物理引擎按固定时间步长模拟（默认 0.02 秒），放在 Update 里帧率变了物理行为就不对。 // 三种施加运动的方式
