    Next *ListNode
}

// reverseList 迭代反转单链表：O(n) 时间，O(1) 空间
func reverseList(head *ListNode) *ListNode {
    var prev *ListNode
    curr := head
    for curr != nil {
        next := curr.Next // 暂存下一个
        curr.Next = prev  // 反转指针
        prev = curr       // 前进一步
        curr = next
    }
    return prev
}

