贪心与回溯 - 资深码农 ~$ 资深码农 后端 数据库 AI 运维 前端 工具 游戏 系统 更多 主页 / 更多技术 / 贪心与回溯 贪心与回溯 🏷️ 算法,贪心,回溯 贪心与回溯：一对性格相反的兄弟 DP 之所以难，是因为它要枚举所有子问题再选最优；而 贪心算法反其道而行 ——每一步都做当前看起来最好的选择，从不回头。它快得多（通常 O(n log n)），但只适用于具备" 贪心选择性质 "的问题：局部最优能推出全局最优。 回溯算法 则是我面试中最爱用的"万能模板"：通过 试错 枚举所有可能，发现走不通就撤销上一步。它本质上是 决策树的 DFS ，配合剪枝能在组合爆炸中找到答案。全排列、子集、N 皇后、括号生成都是回溯的招牌题。 贪心算法：局部最优的合理性证明 贪心最难的不是写代码，而是 证明这个问题可以贪心 。常见套路： 排序后贪心 ：区间调度（按右端点排序选不重叠区间）、会议安排、Huffman 编码。 优先队列贪心 ：任务调度（每次选收益最大的可做任务）、合并果子。 每次选最优局部解 ：跳跃游戏、找零（仅限特定面值）。 经典例题 1：跳跃游戏（贪心） 给定数组 nums[i] 表示在位置 i 能跳的最大长度，问能否跳到最后。贪心思路：实时维护"当前能到达的最远位置 maxReach"，遍历中若 i 超过 maxReach 则失败： package main

import "fmt"

// canJump 贪心：O(n) 时间 O(1) 空间
func canJump(nums []int) bool {
    maxReach := 0
    for i := 0; i < len(nums); i++ {
        if i > maxReach {
            return false // 当前位置已经跳不到
        }
        if i+nums[i] > maxReach {
            maxReach = i + nums[i]
        }
        if maxReach >= len(nums)-1 {
            return true
        }
    }
    return true
}

func main() {
    fmt.Println(canJump([]int{2, 3, 1, 1, 4})) // true
    fmt.Println(canJump([]int{3, 2, 1, 0, 4})) // false（卡在 0）
} Python 对照： from typing import List

def can_jump(nums: List[int]) -> bool:
    max_reach = 0
    for i, x in enumerate(nums):
        if i > max_reach:
            return False
        max_reach = max(max_reach, i + x)
        if max_reach >= len(nums) - 1:
            return True
    return True

